def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", {})
    outcome = result.get("outcome")
    limit = int(result.get("credit_limit", 0) or 0)

    emp = app.get("employment")
    req_limit = app.get("requested_limit")
    try:
        req_limit = int(req_limit)
    except (TypeError, ValueError):
        req_limit = 0

    # Network referral rule: self_employed with requested_limit above 7000
    # must go to manual review instead of being issued. A decline stays a decline.
    if emp == "self_employed" and req_limit > 7000 and outcome == "approved":
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": limit}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    if outcome == "manual_review":
        return {"action": "queue_review", "limit": 0}

    # Fallback: treat as manual review if outcome is unrecognized.
    return {"action": "queue_review", "limit": 0}
